mages/produits/ceinture-1.svg","/images/produits/ceinture-2.svg"],"z":["Unique"],"o":"Or & noir","h":"#C6A15B"},{"c":"femme-accessoires","r":"GL-F-ACC-02","n":"Ceinture fine dorée","s":"ceinture-fine-doree","d":"Ceinture fine en cuir, boucle bijou dorée.","p":28000,"x":null,"g":"femme","f":false,"w":false,"i":["/images/produits/ceinture-2.svg","/images/produits/ceinture-3.svg"],"z":["S","M","L"],"o":"Noir","h":"#111111"},{"c":"femme-accessoires","r":"GL-F-ACC-03","n":"Barrette bijou","s":"barrette-bijou","d":"Barrette ornée de cristaux, finition dorée.","p":18000,"x":null,"g":"femme","f":false,"w":false,"i":["/images/produits/ceinture-3.svg","/images/produits/ceinture-1.svg"],"z":["Unique"],"o":"Or","h":"#C6A15B"}]$j$::jsonb) loop
    insert into public.products (name, slug, reference, description, category_id, collection_id, gender, price, compare_at_price, is_featured, is_new, is_active)
    values (r->>'n', r->>'s', r->>'r', r->>'d', (select id from public.categories where slug = r->>'c'),
            case when (r->>'f')::boolean then (select id from public.collections where slug = 'signature') end,
            (r->>'g')::public.gender, (r->>'p')::int, nullif(r->>'x', '')::int, (r->>'f')::boolean, (r->>'w')::boolean, true)
    on conflict (reference) do nothing returning id into pid;
    continue when pid is null;
    insert into public.product_images (product_id, url, alt, position)
      select pid, u.v, r->>'n', u.o - 1 from jsonb_array_elements_text(r->'i') with ordinality as u(v, o);
    k := 0;
    for sz in select jsonb_array_elements_text(r->'z') loop
      insert into public.product_variants (product_id, size, color, color_hex, sku, position)
        values (pid, sz, r->>'o', r->>'h', (r->>'r') || '-' || upper(regexp_replace(sz, '\s', '', 'g')), k) returning id into vid;
      insert into public.inventory (variant_id, quantity) values (vid, 5);
      k := k + 1;
    end loop;
  end loop;
end $do$;

-- Promotions de démonstration : le 2e produit de chaque catégorie à -20 %
update public.products
   set compare_at_price = (ceil(price / 0.8 / 1000.0) * 1000)::int
 where reference like 'GL-%-02' and compare_at_price is null;
update public.products set is_new = true where reference like 'GL-%-03';

-- Codes de réduction de démonstration (à saisir dans le panier)
insert into public.coupons (code, description, discount_type, value, min_order, max_uses, is_active) values
  ('BIENVENUE10', 'Démo : -10 % sur toute la commande', 'percent', 10, 0, null, true),
  ('GOUNASS5000', 'Démo : -5 000 FCFA dès 50 000 FCFA d''achat', 'fixed', 5000, 50000, null, true),
  ('VIP20', 'Démo : -20 % dès 150 000 FCFA d''achat', 'percent', 20, 150000, null, true)
on conflict (code) do nothing;

